from pathlib import Path
from base64 import b64encode
from html import escape
from datetime import date

OUT = Path(__file__).parent
LOGIN = Path('/private/tmp/ledgify-login.png')

def h(level, text, ident=None):
    anchor = ident or ''.join(c.lower() if c.isalnum() else '-' for c in text).strip('-')
    return f'<h{level} id="{anchor}">{escape(text)}</h{level}>'

def p(text, cls=''):
    return f'<p class="{cls}">{text}</p>'

def ul(items):
    return '<ul>' + ''.join(f'<li>{item}</li>' for item in items) + '</ul>'

def ol(items):
    return '<ol>' + ''.join(f'<li>{item}</li>' for item in items) + '</ol>'

def table(headers, rows):
    return '<table><thead><tr>' + ''.join(f'<th>{x}</th>' for x in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in row) + '</tr>' for row in rows) + '</tbody></table>'

def note(kind, title, text):
    return f'<aside class="{kind}"><strong>{title}</strong><p>{text}</p></aside>'

def shot(caption):
    return f'<figure class="placeholder"><div>AUTHENTICATED SCREENSHOT REQUIRED<br><small>{escape(caption)}</small></div><figcaption>{escape(caption)} — add after a sanitised seeded session is available.</figcaption></figure>'

def chapter(num, title, body):
    return f'<section class="chapter">{h(1, f"{num}. {title}", f"chapter-{num}")}{body}</section>'

