body=[]
body.append(chapter(1,'Introduction to Ledgify',
 p('Ledgify is an organisation-scoped, double-entry accounting application. RC1 connects sales, purchases, banking, inventory, manufacturing, fixed assets, payroll, tax, foreign exchange, consolidation, reports and controlled AI assistance to a Django backend. The web interface is responsive, but wide financial tables may require horizontal scrolling on small screens.')+
 h(2,'Main capabilities')+ul(['Create and manage customers, suppliers, invoices, bills, quotes, orders and credits.','Post balanced journals and inspect account activity and source documents.','Import CSV bank statements, match transactions, cash-code genuine unmatched items and reconcile accounts.','Maintain perpetual weighted-average-cost inventory, stock counts, transfers and returns.','Maintain fixed assets, run accounting depreciation and record disposals.','Run manufacturing work in progress, payroll, tax, FX and full consolidation workflows within the documented limits.','Generate financial reports, ratios and supported CSV, Excel and PDF exports.','Use the AI Assistant for explanations and controlled proposals; it cannot autonomously post high-risk entries.'])+
 h(2,'Saving, approving and posting')+table(['Stage','Meaning','Accounting effect'],[
('Save/Draft','Stores a record for completion or review.','Normally none.'),('Approve','Confirms a commercial or payroll document may proceed.','For invoices and bills, approval posts the accounting entry.'),('Post','Writes a balanced journal to the general ledger.','Reports and account balances change.'),('Reverse/Void','Creates or applies a controlled correction while preserving history.','Original economic effect is neutralised according to the workflow.')])+
 note('warning','Responsibility','Do not approve, post, reverse, void or delete records unless you are authorised and hold appropriate supporting evidence. Posted records should normally be corrected through their source workflow or a documented reversal.')))

